import { readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const dataDir = join(dirname(fileURLToPath(import.meta.url)), "..");
// Generated files are SDK source, so they live with the other types.
const outDir = join(dataDir, "..", "src", "types");

export const readData = (file) => readFileSync(join(dataDir, file), "utf8");
export const readJson = (file) => JSON.parse(readData(file));

export const sortKeys = (obj) =>
    Object.fromEntries(
        Object.entries(obj).sort(([a], [b]) => a.localeCompare(b, "en")),
    );

export const json = (value) => JSON.stringify(value, null, 4);

export function writeGenerated(script, file, source) {
    const banner = `// AUTO-GENERATED by data/scripts/${basename(script)} - do not edit.\n`;
    writeFileSync(join(outDir, file), banner + source);
    console.log(`wrote src/types/${file}`);
}
